#define AA 1
#define PAS_MAX 160
#define DIST_MAX 25.0
#define GRAIN_RES 240.0
#define EXPOSITION 0.55

const vec3 DIR_LUM = vec3(0.6759, 0.6277, 0.3862);

float gHauteur;
float gSolActif;

float hachage13(vec3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}

vec3 hachage33(vec3 p) {
    p = fract(p * vec3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yxz + 33.33);
    return fract((p.xxy + p.yxx) * p.zyx);
}

float bruit3d(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hachage13(i);
    float b = hachage13(i + vec3(1, 0, 0));
    float c = hachage13(i + vec3(0, 1, 0));
    float d = hachage13(i + vec3(1, 1, 0));
    float e = hachage13(i + vec3(0, 0, 1));
    float g = hachage13(i + vec3(1, 0, 1));
    float h = hachage13(i + vec3(0, 1, 1));
    float k = hachage13(i + vec3(1, 1, 1));
    return mix(mix(mix(a, b, f.x), mix(c, d, f.x), f.y),
               mix(mix(e, g, f.x), mix(h, k, f.x), f.y), f.z);
}

vec2 avalanche(vec3 p) {
    float r = length(p.xz) + 1e-4;
    vec2 dir = p.xz / r;
    float base = (gHauteur + 0.5) / 0.62;
    float masque = smoothstep(0.10, 0.35, r)
                 * (1.0 - smoothstep(base - 0.2, base + 0.3, r))
                 * gSolActif;
    if (masque <= 0.0) return vec2(0.0);

    float n = 0.65 * bruit3d(vec3(dir * 4.0, r * 1.1 - iTime * 0.50))
            + 0.35 * bruit3d(vec3(dir * 8.5 + 7.3, r * 2.3 - iTime * 0.80 + 4.0));

    float canal = smoothstep(0.50, 0.66, n) * masque;
    float x = (n - 0.52) / 0.05;
    float bord = exp(-x * x) * masque;
    return vec2(canal, bord);
}

float sdSable(vec3 p) {

    float sol = p.y + 0.5 + (bruit3d(p * vec3(5.0, 1.0, 5.0)) - 0.5) * 0.05;
    sol += 0.003 * sin(dot(p.xz, vec2(0.8, 0.6)) * 55.0
                       + sin(p.x * 3.1) * sin(p.z * 2.7) * 5.0);

    float rayon = sqrt(dot(p.xz, p.xz) + 0.006);
    float cone = (p.y - (gHauteur - rayon * 0.62)) * 0.85;
    cone += (bruit3d(vec3(p.xz * 9.0, p.y * 3.0)) - 0.5) * 0.035;

    vec2 av = avalanche(p);
    cone += av.x * 0.010 - av.y * 0.008;

    float m = clamp(0.5 + 0.5 * (cone - sol) / 0.1, 0.0, 1.0);
    return mix(cone, sol, m) - 0.1 * m * (1.0 - m)
         + (bruit3d(p * 90.0) - 0.5) * 0.008;
}

vec3 grainsCoulants(vec3 p, float decalage) {
    float r = length(p.xz) + 1e-4;
    vec3 sens = vec3(p.x / r, -0.62, p.z / r);
    float T = 1.4;
    float ph0 = fract(iTime / T);
    float ph1 = fract(iTime / T + 0.5);
    float w0 = 1.0 - abs(1.0 - 2.0 * ph0);
    vec3 g0 = hachage33(floor((p - sens * ph0 * 0.7) * GRAIN_RES) + 31.0 + decalage);
    vec3 g1 = hachage33(floor((p - sens * ph1 * 0.7) * GRAIN_RES) + 57.0 + decalage);
    return mix(g1, g0, w0);
}

vec3 fondCiel(vec3 rd) {
    float h = clamp(rd.y * 2.0 + 0.2, 0.0, 1.0);
    return pow(mix(vec3(0.88, 0.78, 0.62), vec3(0.42, 0.55, 0.70), h), vec3(2.2)) * 1.5;
}

vec3 ciel(vec3 rd) {
    vec3 c = fondCiel(rd);
    float s = max(dot(rd, DIR_LUM), 0.0);
    c += vec3(1.0, 0.72, 0.42) * pow(s, 6.0) * 0.45;
    c += vec3(1.0, 0.85, 0.60) * pow(s, 64.0) * 0.8;
    c += vec3(1.0, 0.92, 0.75) * pow(s, 700.0) * 6.0;
    return c;
}

float ombreDouce(vec3 ro, vec3 rd) {
    float res = 1.0;
    float t = 0.03;
    for (int i = 0; i < 40; i++) {
        float h = sdSable(ro + rd * t);
        if (h < 0.0008) return 0.0;
        res = min(res, 14.0 * h / t);
        t += max(h, 0.01);
        if (t > 6.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

float occlusion(vec3 p, vec3 n) {
    float occ = 0.0;
    float s = 1.0;
    for (int i = 1; i <= 5; i++) {
        float h = 0.035 * float(i);
        occ += (h - sdSable(p + n * h)) * s;
        s *= 0.6;
    }
    return clamp(1.0 - 3.0 * occ, 0.0, 1.0);
}

vec3 rendre(vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float angleCam = iTime * 0.12 + 0.6;
    vec3 ro = vec3(5.0 * sin(angleCam), 1.9, 5.0 * cos(angleCam));
    vec3 cible = vec3(0.0, 0.35, 0.0);
    vec3 dirAvant = normalize(cible - ro);
    vec3 dirDroite = normalize(cross(dirAvant, vec3(0.0, 1.0, 0.0)));
    vec3 dirHaut = cross(dirDroite, dirAvant);
    vec3 rd = normalize(uv.x * dirDroite + uv.y * dirHaut + 1.6 * dirAvant);

    vec3 couleur = ciel(rd);

    float t = 0.0;
    bool impact = false;
    for (int i = 0; i < PAS_MAX; i++) {
        vec3 p = ro + rd * t;
        float d = sdSable(p);
        if (d < 0.0015 + 0.0005 * t) { impact = true; break; }
        t += max(d, 0.002) * 0.75;
        if (t > DIST_MAX) break;
    }

    if (impact) {
        vec3 p = ro + rd * t;
        vec2 e = vec2(0.004, -0.004);
        vec3 normale = normalize(e.xyy * sdSable(p + e.xyy)
                               + e.yyx * sdSable(p + e.yyx)
                               + e.yxy * sdSable(p + e.yxy)
                               + e.xxx * sdSable(p + e.xxx));

        float empreinte = t / (1.6 * iResolution.y * float(AA));
        float k = 1.0 - clamp(empreinte * GRAIN_RES * 0.6, 0.0, 1.0);

        vec2 av = avalanche(p);
        float canal = av.x;
        vec3 cellule = floor(p * GRAIN_RES);
        vec3 g  = mix(hachage33(cellule), grainsCoulants(p, 0.0), canal);
        vec3 gB = mix(hachage33(cellule + 3.3), grainsCoulants(p, 100.0), canal);

        vec3 albedo = mix(vec3(0.66, 0.50, 0.30), vec3(0.90, 0.76, 0.52), mix(0.5, g.x, k));
        albedo *= 0.85 + 0.3 * bruit3d(p * 6.0);
        albedo = mix(albedo, vec3(0.35, 0.26, 0.16), step(0.93, g.y) * 0.5 * k);
        albedo = pow(albedo, vec3(2.2));
        albedo *= 1.0 + 0.10 * canal;

        vec3 n = normalize(normale + (g.zxy - 0.5) * 0.35 * k);

        float ndl = dot(n, DIR_LUM);
        float diffuse = clamp(ndl, 0.0, 1.0);
        float wrap = clamp((ndl + 0.25) / 1.25, 0.0, 1.0);
        float retro = pow(clamp(dot(-rd, DIR_LUM), 0.0, 1.0), 2.0) * 0.35;

        float ombre = ombreDouce(p + normale * 0.01, DIR_LUM);
        float ao = occlusion(p, normale);

        vec3 soleil = pow(vec3(1.1, 0.95, 0.75), vec3(1.6)) * 3.0;
        float direct = (0.7 * diffuse + 0.3 * wrap) * (1.0 + retro);
        vec3 ambiante = pow(mix(vec3(0.25, 0.22, 0.20), vec3(0.40, 0.50, 0.60),
                                n.y * 0.5 + 0.5), vec3(2.2)) * 2.2;

        couleur = albedo * (soleil * direct * ombre * mix(1.0, ao, 0.4)
                          + ambiante * ao);

        vec3 gn = normalize(normale + (gB.yzx - 0.5) * 1.8);
        vec3 demi = normalize(DIR_LUM - rd);
        float paillette = pow(max(dot(gn, demi), 0.0), 120.0)
                        * step(0.92, gB.x) * sqrt(k);
        couleur += soleil * paillette * ombre * 0.9;

        float brouillard = 1.0 - exp(-0.0025 * t * t);
        couleur = mix(couleur, fondCiel(rd), brouillard);
    } else {
        t = DIST_MAX;
    }

    vec3 couleurParticules = vec3(0.0);
    float transparence = 1.0;
    float poussiere = 0.0;
    float rayonCylindre = 0.3;

    vec2 orig2D = ro.xz;
    vec2 dir2D = rd.xz;
    float a = dot(dir2D, dir2D);
    float b = dot(orig2D, dir2D);
    float c = dot(orig2D, orig2D) - rayonCylindre * rayonCylindre;
    float discriminant = b * b - a * c;

    if (discriminant > 0.0 && a > 1e-4 && gSolActif > 0.0) {
        float racine = sqrt(discriminant);
        float t0 = max((-b - racine) / a, 0.0);
        float t1 = min((-b + racine) / a, t);
        if (t1 > t0) {
            float pas = (t1 - t0) / 96.0;
            for (int i = 0; i < 96; i++) {
                float ti = t0 + pas * (float(i) + 0.5);
                vec3 p = ro + rd * ti;
                if (p.y > 5.0) continue;

                vec2 centre = p.xz - 0.012 * vec2(sin(p.y * 6.0 + iTime * 4.0),
                                                  cos(p.y * 5.0 + iTime * 3.0));
                float rayonDist = length(centre);
                float surfY = max(gHauteur - length(p.xz) * 0.62, -0.5);
                float auDessus = p.y - surfY;

                float densite = 1.0 - smoothstep(0.03, 0.06, rayonDist);
                float dispersion = step(0.0, auDessus)
                                 * exp(-max(auDessus, 0.0) * 8.0)
                                 * (1.0 - smoothstep(0.05, 0.3, rayonDist));
                densite = clamp(densite + 0.12 * dispersion, 0.0, 1.0) * gSolActif;

                poussiere += pas * 5.0 * dispersion
                           * (0.5 + bruit3d(p * 12.0 + vec3(0.0, iTime * 2.0, 0.0)))
                           * gSolActif;

                float echelle = 95.0;
                vec2 cellule = floor(centre * echelle);
                float vitesse = hachage13(vec3(cellule, 3.1));
                float gy = p.y * echelle * 0.4 + iTime * (120.0 + 60.0 * vitesse);
                float cy = floor(gy);
                vec3 h = hachage33(vec3(cellule, cy));

                vec2 posLocale = fract(centre * echelle) - 0.5;
                float distGrain = length(posLocale - (h.yz - 0.5) * 0.3);

                if (h.x < densite * 0.5 && distGrain < 0.3) {
                    vec3 grain = pow(mix(vec3(0.62, 0.47, 0.28), vec3(0.96, 0.84, 0.62), h.z),
                                     vec3(2.2)) * (0.75 + 0.5 * h.y) * 2.4;
                    float alpha = 0.75;
                    couleurParticules += transparence * alpha * grain;
                    transparence *= 1.0 - alpha;
                    if (transparence < 0.03) break;
                }
            }
        }
    }

    couleur = couleur * transparence + couleurParticules;

    float attenPoussiere = 1.0 - exp(-poussiere);
    vec3 couleurPoussiere = pow(vec3(0.85, 0.74, 0.56), vec3(2.2)) * 1.8;
    couleur = mix(couleur, couleurPoussiere, attenPoussiere * 0.35);

    return couleur;
}

vec3 aces(vec3 x) {
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float tMod = mod(iTime, 16.0);
    gHauteur = -0.9 + 1.9 * pow(clamp(tMod / 13.0, 0.0, 1.0), 0.34)
             - 2.5 * smoothstep(14.5, 16.0, tMod);
    gSolActif = 1.0 - smoothstep(13.0, 13.3, tMod);

    vec3 acc = vec3(0.0);
    for (int j = 0; j < AA; j++) {
        for (int i = 0; i < AA; i++) {
            vec2 o = (vec2(float(i), float(j)) + 0.5) / float(AA) - 0.5;
            acc += rendre(fragCoord + o);
        }
    }
    acc /= float(AA * AA);

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 c = aces(acc * EXPOSITION);
    c = pow(c, vec3(1.0 / 2.2));
    c *= 1.0 - 0.35 * dot(uv, uv);
    c += (hachage13(vec3(fragCoord, fract(iTime) * 100.0)) - 0.5) / 255.0;

    fragColor = vec4(c, 1.0);
}
